create temporary view dwd_user_location_${grass_region_without_quote} as
select
    user_id
    ,case when is_ads is true then 'true' else 'false' end as is_ads
    ,case
        when reporting_module in ('Daily Discover') then coalesce(split(feature_detail, '-') [2], 'NULL')
        when source1_reporting_module in ('Daily Discover') then coalesce(split(source1_feature_detail, '-') [2], 'NULL')
        when source2_reporting_module in ('Daily Discover') then coalesce(split(source2_feature_detail, '-') [2], 'NULL')
    end as card_type
    ,case
        when reporting_module in ('Daily Discover') then least(coalesce(location, -1), 200)
        when source1_reporting_module in ('Daily Discover') then least(coalesce(source1_location, -1), 200)
        when source2_reporting_module in ('Daily Discover') then least(coalesce(source2_location, -1), 200)
    end as location
    ,sum(case when operation = 'impression' then operation_cnt else 0 end) as imp_cnt
    ,sum(case when operation = 'click' then operation_cnt else 0 end) as click_cnt
    ,sum(case when operation = 'omni_impression' then operation_cnt else 0 end) as omni_imp_cnt
    ,sum(case when operation = 'omni_click' then operation_cnt else 0 end) as omni_click_cnt
    ,sum(case when operation = 'ppv' and is_back = false then operation_cnt else 0 end) as ppv_cnt
    ,sum(case when operation = 'order' then operation_cnt else 0 end) as order_cnt
    ,sum(case when operation = 'order' then place_order_gmv else 0 end) as gmv
    ,sum(case when operation = 'order' then pc2_gmv else 0 end) as pc2_gmv
from
    srdi_mart.dwd_sr_data_warehouse_platform
where
    grass_region = ${grass_region}
    and local_date = ${local_date}
    and operation in ('impression', 'click', 'omni_impression', 'omni_click', 'ppv', 'order')
    and (
        reporting_module in ('Daily Discover')
        or source1_reporting_module in ('Daily Discover')
        or source2_reporting_module in ('Daily Discover')
    )
    and user_id > 0
    and (operation_cnt > 0 or place_order_gmv > 0 or pc2_gmv > 0)
group by 1, 2, 3, 4
;

