create temporary view dwd_user_location_joined_${grass_region_without_quote} as
select
    t1.user_id
    ,is_ads
    ,card_type
    ,location
    ,imp_cnt
    ,click_cnt
    ,omni_imp_cnt
    ,omni_click_cnt
    ,ppv_cnt
    ,order_cnt
    ,gmv
    ,pc2_gmv
    ,coalesce(user_purchase_type, 0) as user_purchase_type
