cache table user_location_cube_pre_${grass_region_without_quote} as
select
    user_purchase_type
    ,platform
    ,location
    ,coalesce(card_type, '__ALL__') as card_type
    ,coalesce(is_ads, '__ALL__') as is_ads
    ,sum(imp_cnt) as imp_cnt
    ,sum(click_cnt) as click_cnt
    ,sum(omni_imp_cnt) as omni_imp_cnt
