    ,sum(ppv_cnt) as ppv_cnt
    ,sum(order_cnt) as order_cnt
    ,sum(gmv) as gmv
    ,sum(pc2_gmv) as pc2_gmv
    ,count(distinct if(imp_cnt > 0, user_id, null)) as imp_uu
    ,count(distinct if(click_cnt > 0, user_id, null)) as click_uu
    ,count(distinct if(order_cnt > 0, user_id, null)) as order_uu
    ,sum(if(is_ads = 'true', imp_cnt, 0)) as ads_imp_cnt
from
    dwd_user_location_joined_${grass_region_without_quote}
group by grouping sets (
    (location, user_purchase_type, platform)
    ,(location, user_purchase_type, platform, card_type)
    ,(location, user_purchase_type, platform, is_ads)
    ,(location, user_purchase_type, platform, card_type, is_ads)
);

