create temporary view user_location_cube_final_${grass_region_without_quote} as
select
    *
from
    user_location_cube_pre_${grass_region_without_quote}

union all
select
    coalesce(user_purchase_type, -1) as user_purchase_type
    ,coalesce(platform, '__ALL__') as platform
    ,location
    ,card_type
    ,is_ads
    ,sum(imp_cnt) as imp_cnt
    ,sum(click_cnt) as click_cnt
    ,sum(omni_imp_cnt) as omni_imp_cnt
    ,sum(omni_click_cnt) as omni_click_cnt
    ,sum(ppv_cnt) as ppv_cnt
    ,sum(order_cnt) as order_cnt
    ,sum(gmv) as gmv
    ,sum(pc2_gmv) as pc2_gmv
    ,sum(imp_uu) as imp_uu
    ,sum(click_uu) as click_uu
    ,sum(order_uu) as order_uu
    ,sum(ads_imp_cnt) as ads_imp_cnt
from
    user_location_cube_pre_${grass_region_without_quote}
group by grouping sets (
    (location, card_type, is_ads)
    ,(location, card_type, is_ads, user_purchase_type)
    ,(location, card_type, is_ads, platform)
);

