create temporary view traffic_metrics_${grass_region_without_quote} as
select
    t1.user_purchase_type
    ,t1.platform
    ,t1.location
    ,t1.card_type
    ,t1.is_ads
    ,imp_cnt
    ,click_cnt
    ,omni_imp_cnt
    ,omni_click_cnt
    ,ppv_cnt
    ,order_cnt
    ,gmv
    ,pc2_gmv
    ,imp_uu
    ,click_uu
    ,order_uu
    ,if(imp_cnt > 0, click_cnt / imp_cnt, 0) as ctr
    ,if(click_cnt > 0, order_cnt / click_cnt, 0) as cr
    ,if(imp_cnt > 0, order_cnt / imp_cnt, 0) as co
    ,if(imp_uu > 0, click_uu / imp_uu, 0) as uv_ctr
    ,if(click_uu > 0, order_uu / click_uu, 0) as uv_cr
    ,if(imp_uu > 0, order_uu / imp_uu, 0) as uv_co
    ,if(location_imp > 0, imp_cnt / location_imp, 0) as imp_perc
    ,if(location_click > 0, click_cnt / location_click, 0) as click_perc
    ,if(location_order > 0, order_cnt / location_order, 0) as order_perc
    ,if(location_gmv > 0, gmv / location_gmv, 0) as gmv_perc
    ,if(location_pc2 > 0, pc2_gmv / location_pc2, 0) as pc2_perc
    ,if(ttl_imp > 0, ads_imp_cnt / ttl_imp, 0) as ads_load
    ,if(imp_cnt > 0, order_cnt * 1000 / imp_cnt, 0) as opm
    ,if(imp_cnt > 0, gmv * 1000 / imp_cnt, 0) as gpm
from
    user_location_cube_final_${grass_region_without_quote} as t1
left join (
    select
        user_purchase_type
        ,platform
        ,location
        ,card_type
        ,is_ads
        ,imp_cnt as location_imp
        ,click_cnt as location_click
        ,order_cnt as location_order
        ,gmv as location_gmv
        ,pc2_gmv as location_pc2
    from user_location_cube_final_${grass_region_without_quote}
    where
        card_type = '__ALL__'
        and is_ads = '__ALL__'
) as t2
on 
    t1.user_purchase_type = t2.user_purchase_type
    and t1.platform = t2.platform
    and t1.location = t2.location
left join (
    select
        user_purchase_type
        ,platform
        ,sum(imp_cnt) as ttl_imp
    from user_location_cube_final_${grass_region_without_quote}
    where
        card_type = '__ALL__'
        and is_ads = '__ALL__'
    group by 1, 2
) as t3
on 
    t1.user_purchase_type = t3.user_purchase_type
    and t1.platform = t3.platform
;

