create temporary view ads_revenue_base_${grass_region_without_quote} as
select
    user_id
    ,case
        when entrance = 3 then least(coalesce(location, -1), 200)
        else -999
    end as location --只有外流revenue记录location，内流的部分统一记录location为-999
    ,case
        when entrance in (25, 31, 32) then 'item_mix_feed_card'
        when entrance in (34, 56) then 'video'
        else target_type
    end as card_type
    ,sum(coalesce(expenditure_amt_usd, 0)) as ads_revenue
from
    mp_paidads.dwd_advertise_performance_di__reg_s0_live
where
    grass_region = ${grass_region}
    and grass_date = ${local_date}
    and tz_type = 'local'
    and user_id > 0
    and entrance in (3, 25, 31, 32, 34, 56)
group by 1, 2, 3
;

--sql_divide_splitter--
create temporary view ads_revenue_joined_${grass_region_without_quote} as
select
    location
    ,coalesce(user_purchase_type, 0) as user_purchase_type
    ,coalesce(platform, 'NULL') as platform
    ,coalesce(card_type, 'NULL') as card_type
    ,sum(coalesce(ads_revenue, 0)) as ads_revenue
from
    ads_revenue_base_${grass_region_without_quote} as t1
    left join dim_user_label_${grass_region_without_quote} as t2
    on t1.user_id = t2.user_id
group by 1, 2, 3, 4
;

--sql_divide_splitter--
cache table ads_metrics_${grass_region_without_quote} as
select
    location
    ,coalesce(user_purchase_type, -1) as user_purchase_type
    ,coalesce(platform, '__ALL__') as platform
    ,coalesce(card_type, '__ALL__') as card_type
    ,sum(ads_revenue) as ads_revenue
from
    ads_revenue_joined_${grass_region_without_quote}
group by grouping sets (
    (location, user_purchase_type, platform, card_type)
    ,(location, user_purchase_type, platform)
    ,(location, user_purchase_type, card_type)
    ,(location, platform, card_type)
    ,(location, user_purchase_type)
    ,(location, platform)
    ,(location, card_type)
    ,(location)
);

--sql_divide_splitter--
insert overwrite table ${schema}.dws_sr_data_warehouse_homepage_dd_location_1d
partition (grass_region = ${grass_region}, local_date = ${local_date})
select
    case
        when coalesce(t1.user_purchase_type, t2.user_purchase_type) = -1 then '__ALL__'
        when coalesce(t1.user_purchase_type, t2.user_purchase_type) = 0 then 'non-buyer'
        when coalesce(t1.user_purchase_type, t2.user_purchase_type) = 1 then 'buyer'
     end as user_purchase_type
    ,coalesce(t1.platform, t2.platform) as platform
    ,coalesce(t1.location, t2.location) as location
    ,coalesce(t1.card_type, t2.card_type) as card_type
    ,coalesce(t1.is_ads, t2.is_ads) as is_ads

    ,coalesce(imp_cnt, 0) as imp_cnt
    ,coalesce(click_cnt, 0) as click_cnt
    ,coalesce(omni_imp_cnt, 0) as omni_imp_cnt
    ,coalesce(omni_click_cnt, 0) as omni_click_cnt
    ,coalesce(ppv_cnt, 0) as ppv_cnt
    ,coalesce(order_cnt, 0) as order_cnt
    ,coalesce(gmv, 0) as gmv
    ,coalesce(pc2_gmv, 0) as pc2_gmv
    ,coalesce(imp_uu, 0) as imp_uu
    ,coalesce(click_uu, 0) as click_uu
    ,coalesce(order_uu, 0) as order_uu
    ,coalesce(ctr, 0) as ctr
    ,coalesce(cr, 0) as cr
    ,coalesce(co, 0) as co
    ,coalesce(uv_ctr, 0) as uv_ctr
    ,coalesce(uv_cr, 0) as uv_cr
    ,coalesce(uv_co, 0) as uv_co
    ,coalesce(imp_perc, 0) as imp_perc
    ,coalesce(click_perc, 0) as click_perc
    ,coalesce(order_perc, 0) as order_perc
    ,coalesce(gmv_perc, 0) as gmv_perc
    ,coalesce(pc2_perc, 0) as pc2_perc
    ,coalesce(ads_load, 0) as ads_load
    ,coalesce(opm, 0) as opm
    ,coalesce(gpm, 0) as gpm
    ,coalesce(ads_revenue, 0) as ads_revenue
from
    traffic_metrics_${grass_region_without_quote} as t1
full outer join (
    select *, 'true' as is_ads from ads_metrics_${grass_region_without_quote}
    union all
    select *, '__ALL__' as is_ads from ads_metrics_${grass_region_without_quote}
) as t2
on 
    t1.user_purchase_type = t2.user_purchase_type
    and t1.platform = t2.platform
    and t1.location = t2.location
    and t1.card_type = t2.card_type
    and t1.is_ads = t2.is_ads
;
